<?php
require_once __DIR__ . '/../includes/auth-check.php';
require_once __DIR__ . '/../includes/admin-ui.php';
require_once __DIR__ . '/../includes/analytics.php';
admin_require_permission($pdo,$admin,'manage_affiliates');
$errorMessage='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=request_string($_POST, 'action', 'save');$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT)?:0;
 try{
  if($action==='delete'){if(!$id)throw new RuntimeException('Invalid affiliate link.');$pdo->prepare('DELETE FROM affiliate_links WHERE id=:id')->execute(['id'=>$id]);audit_log($pdo,(int)$admin['id'],'affiliate.deleted','affiliate_link',(string)$id);flash('success','Affiliate link removed.');redirect_to('admin/affiliates.php');}
  $label=trim(substr(strip_tags(request_string($_POST, 'label', '')),0,180));$slug=slugify(request_string($_POST, 'slug', $label));$target=trim(substr(request_string($_POST, 'destination_url', ''),0,1000));$active=isset($_POST['is_active'])?1:0;
  if($label===''||$slug===''||!filter_var($target,FILTER_VALIDATE_URL)||strtolower((string)parse_url($target,PHP_URL_SCHEME))!=='https')throw new RuntimeException('Enter a label, slug and valid HTTPS destination URL.');
  $duplicate=$pdo->prepare('SELECT id FROM affiliate_links WHERE slug=:slug AND id<>:id LIMIT 1');$duplicate->execute(['slug'=>$slug,'id'=>$id]);if($duplicate->fetchColumn())throw new RuntimeException('That redirect slug is already in use.');
  if($id){$save=$pdo->prepare('UPDATE affiliate_links SET slug=:slug,label=:label,destination_url=:target,is_active=:active,updated_by=:admin WHERE id=:id');$save->execute(['slug'=>$slug,'label'=>$label,'target'=>$target,'active'=>$active,'admin'=>(int)$admin['id'],'id'=>$id]);}
  else{$save=$pdo->prepare('INSERT INTO affiliate_links(slug,label,destination_url,is_active,created_by,updated_by) VALUES(:slug,:label,:target,:active,:created_by,:updated_by)');$save->execute(['slug'=>$slug,'label'=>$label,'target'=>$target,'active'=>$active,'created_by'=>(int)$admin['id'],'updated_by'=>(int)$admin['id']]);$id=(int)$pdo->lastInsertId();}
  audit_log($pdo,(int)$admin['id'],'affiliate.saved','affiliate_link',(string)$id,'Link configuration saved.');flash('success','Affiliate link saved.');redirect_to('admin/affiliates.php');
 }catch(Throwable $error){if($pdo->inTransaction())$pdo->rollBack();error_log('Affiliate link save: '.$error->getMessage());$errorMessage=$error instanceof RuntimeException?$error->getMessage():'Affiliate link could not be saved.';}
}
$editing=null;if(isset($_GET['edit'])){$get=$pdo->prepare('SELECT * FROM affiliate_links WHERE id=:id');$get->execute(['id'=>filter_var($_GET['edit'],FILTER_VALIDATE_INT)]);$editing=$get->fetch()?:null;}
$links=$pdo->query('SELECT a.id,a.slug,a.label,a.destination_url,a.is_active,COUNT(c.id) AS total_clicks,SUM(c.clicked_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)) AS clicks_30d FROM affiliate_links a LEFT JOIN affiliate_clicks c ON c.affiliate_link_id=a.id GROUP BY a.id ORDER BY a.created_at DESC')->fetchAll();
admin_header($pdo,$admin,'Affiliate links');
?>
<?php if($errorMessage!==''):?><div class="notice notice-error" role="alert"><?=e($errorMessage)?></div><?php endif;?>
<div class="admin-columns"><section class="admin-card"><h2><?= $editing?'Edit':'Add' ?> redirect</h2><p>Public route: <code>/go/your-slug</code>. Only HTTPS destinations are allowed. Click counts exclude ad clicks and store no raw IP address.</p><form class="admin-form" method="post"><?=csrf_field()?><?php if($editing):?><input type="hidden" name="id" value="<?=(int)$editing['id']?>"><?php endif;?><div class="field"><label for="label">Link label</label><input id="label" name="label" maxlength="180" required value="<?=e($editing['label']??'')?>"></div><div class="field"><label for="slug">Short slug</label><input id="slug" name="slug" maxlength="120" pattern="[a-z0-9]+(-[a-z0-9]+)*" required value="<?=e($editing['slug']??'')?>"></div><div class="field"><label for="destination_url">HTTPS destination URL</label><input id="destination_url" name="destination_url" type="url" maxlength="1000" required value="<?=e($editing['destination_url']??'')?>"></div><label class="inline-check"><input type="checkbox" name="is_active" value="1" <?=!$editing||$editing['is_active']?'checked':''?>><span>Enable redirect and count clicks</span></label><div class="admin-actions"><button class="button button-primary" type="submit">Save redirect</button><?php if($editing):?><a class="button button-small" href="<?=e(app_url('admin/affiliates.php'))?>">Cancel</a><?php endif;?></div></form></section>
<section class="admin-card"><h2>Configured links</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Label / route</th><th>Destination</th><th>Clicks</th><th>Actions</th></tr></thead><tbody><?php foreach($links as $link):?><tr><td><strong><?=e($link['label'])?></strong><br><code>/go/<?=e($link['slug'])?></code><br><span class="admin-badge"><?=$link['is_active']?'Active':'Disabled'?></span></td><td><a href="<?=e($link['destination_url'])?>" target="_blank" rel="noopener noreferrer nofollow">Open target ↗</a></td><td><?=number_format((int)$link['total_clicks'])?> total<br><small><?=number_format((int)$link['clicks_30d'])?> last 30 days</small></td><td><div class="admin-actions"><a href="<?=e(app_url('admin/affiliates.php?edit='.(int)$link['id']))?>">Edit</a><form method="post" data-confirm="Delete this redirect and its click records?"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$link['id']?>"><button class="admin-danger" type="submit">Delete</button></form></div></td></tr><?php endforeach;?><?php if(!$links):?><tr><td colspan="4">No affiliate redirects configured.</td></tr><?php endif;?></tbody></table></div></section></div>
<?php admin_footer(); ?>
